syntax:
template <typename T>
ReturnType functionName(Parameters) {
    // function implementation using type T
}

code_example:
#include <iostream>
template <typename T>
T max(T a, T b) {
    return (a > b) ? a : b;
}
int main() {
    std::cout << max(3, 7) << std::endl; // Instantiates max<int>
    std::cout << max(3.14, 2.71) << std::endl; // Instantiates max<double>
    std::cout << max('a', 'z') << std::endl; // Instantiates max<char>
    return 0;
}
